def bf(planet1, planet2):
    planets_order = {
        "Mercury": 1,
        "Venus": 2,
        "Earth": 3,
        "Mars": 4,
        "Jupiter": 5,
        "Saturn": 6,
        "Uranus": 7,
        "Neptune": 8
    }

    if planet1 not in planets_order or planet2 not in planets_order:
        return ()

    start = min(planets_order[planet1], planets_order[planet2])
