def modp(n: int, p: int):
    def calculate_power(base, exponent):
        if exponent == 0:
            return 1
        result = 1
        for _ in range(exponent):
            result *= base
        return result

    def calculate_modulo(base, mod):
        return base % mod

    power_result = calculate_power(2, n)
    modulo_result = calculate_modulo(power_result, p)
    return modulo_result

