def int_to_mini_roman(number):
    def digit_to_roman(digit, one, five, ten):
        if digit == 9:
            return one + ten
        elif digit >= 5:
            return five + one * (digit - 5)
        elif digit == 4:
            return one + five
        else:
            return one * digit

    if not 1 <= number <= 1000:
        return "Number out of range"

    ones = number % 10
    tens = (number // 10) % 10
    hundreds = (number // 100) % 10
    thousands = number // 1000

    roman_ones = digit_to_roman(ones, 'i', 'v', 'x')
    roman_tens = digit_to_roman(tens, 'x', 'l', 'c')
    roman_hundreds = digit_to_roman(hundreds, 'c', 'd', 'm')
    roman_thousands = 'm' * thousands

    return roman_thousands + roman_hundreds + roman_tens + roman_ones

