def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit_values = {planet: index for index, planet in enumerate(planets)}

    start = min(orbit_values[planet1], orbit_values[planet2])
    end = max(orbit_values[planet1], orbit_values[planet2])

    result = [planet for planet in planets if start < orbit_values[planet] < end]

    return tuple(sorted(result, key=lambda x: orbit_values[x]))

