def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]
    orbits = {
        "Mercury": 1,
        "Venus": 2,
        "Earth": 3,
        "Mars": 4,
        "Jupiter": 5,
        "Saturn": 6,
        "Uranus": 7,
        "Neptune": 8
    }

    if planet1 not in planets or planet2 not in planets:
        return ()

    orbit1 = orbits[planet1]
    orbit2 = orbits[planet2]

    if orbit1 == orbit2:
        return ()

    start = min(orbit1, orbit2)
    end = max(orbit1, orbit2)

    result = [planet for planet, orbit in orbits.items() if start < orbit < end]
    result.sort(key=lambda x: orbits[x])

    return tuple(result)
